    private void connectionSnapshot()throws Exception{
        String name="connection-"+UUID.randomUUID()+".db";Store f=new Store(target,name);try{
            f.configureBackup("https://a.fixture","a-fixture");Thread writer=new Thread(()->{for(int i=0;i<200;i++)f.configureBackup(i%2==0?"https://a.fixture":"https://b.fixture",i%2==0?"a-fixture":"b-fixture");});writer.start();
            java.lang.reflect.Field base=Api.class.getDeclaredField("base"),token=Api.class.getDeclaredField("token");base.setAccessible(true);token.setAccessible(true);
            for(int i=0;i<200;i++){Api a=new Api((CareApp)target.getApplicationContext(),f,(m,p,b)->Store.obj());String b=(String)base.get(a),t=(String)token.get(a);equal(true,b.equals("https://a.fixture")&&t.equals("a-fixture")||b.equals("https://b.fixture")&&t.equals("b-fixture"));}writer.join();
            String old=UUID.randomUUID().toString();f.request(old,"qa","legacy");f.set("request_transport_"+old,"");try{AiEngine.frozenProvider(f,old);throw new AssertionError("legacy request rebound");}catch(IOException expected){assertions++;}
            String direct=UUID.randomUUID().toString();f.set("request_provider_"+direct,"{\"id\":\"captured-service\"}");f.request(direct,"qa","frozen");equal("captured-service",AiEngine.frozenProvider(f,direct).optString("id"));
        }finally{f.close();target.deleteDatabase(name);}log.append("Atomic backup URL/token snapshots and missing-provider request rejection: PASS\n");
    }
    private void instanceFence()throws Exception{
        String name="instance-"+UUID.randomUUID()+".db";Store f=new Store(target,name);try{
            f.set("base_url","https://fixture.invalid");String server=UUID.randomUUID().toString(),profile=UUID.randomUUID().toString();final String[] active={server};final int[] pushes={0};
            Api a=new Api((CareApp)target.getApplicationContext(),f,(method,path,body)->{
                if(path.equals("/capabilities"))return Store.obj("protocol","personal-api-v1","instance_context_required",true,"server_instance_id",active[0],"profiles",new JSONArray().put(Store.obj("id","baby","instance_id",profile,"generation",1)));
                if(path.equals("/profiles"))return Store.obj("items",new JSONArray().put(Store.obj("id","baby","instance_id",profile,"generation",1)));
                if(path.startsWith("/sync/pull"))return Store.obj("through",0,"next_cursor",0,"changes",new JSONArray(),"has_more",false);
                if(path.equals("/sync/push")){pushes[0]++;JSONObject op=body.getJSONArray("operations").getJSONObject(0);equal(profile,op.optString("profile_instance_id"));return Store.obj("receipts",new JSONArray().put(Store.obj("operation_id",op.optString("operation_id"),"status","applied","revision",1)));}
                throw new IOException("unexpected fixture path");
            });
            // Existing local intent must not receive identities discovered later.
            String localId=f.save(Store.obj("kind","feeding","start",System.currentTimeMillis(),"amount",10));f.toggleSleep(System.currentTimeMillis()-10000);equal(true,a.sync());equal(0,pushes[0]);equal("instance_context_missing",f.query("SELECT error FROM outbox").get(0).optString("error"));
            f.toggleSleep(System.currentTimeMillis());equal("",Store.json(f.query("SELECT body FROM outbox ORDER BY seq DESC").get(0).optString("body")).getJSONObject("_sync_context").optString("server"));JSONObject oldEditor=f.timeline(0,System.currentTimeMillis()+1000).stream().filter(e->localId.equals(e.optString("id"))).findFirst().get();oldEditor.put("amount",11);f.save(oldEditor);equal("",Store.json(f.query("SELECT body FROM outbox ORDER BY seq DESC").get(0).optString("body")).getJSONObject("_sync_context").optString("server"));f.delete(localId);equal("",Store.json(f.query("SELECT body FROM outbox ORDER BY seq DESC").get(0).optString("body")).getJSONObject("_sync_context").optString("server"));
            JSONObject next=Store.obj("kind","feeding","start",System.currentTimeMillis(),"amount",20);f.save(next);equal(true,a.sync());equal(1,pushes[0]);
            String direct=UUID.randomUUID().toString();f.set("request_provider_"+direct,"{\"id\":\"user-service\"}");f.request(direct,"qa","direct ownership");equal(true,a.sync());equal("queued",f.requestById(direct).optString("status"));a.processJobs();equal("queued",f.requestById(direct).optString("status"));new Api((CareApp)target.getApplicationContext(),f,(m,p,b)->{throw new IOException("offline capabilities");}).processJobs();equal("queued",f.requestById(direct).optString("status"));
            JSONObject editor=Store.json(next.toString());active[0]=UUID.randomUUID().toString();equal(false,a.sync());equal(server,f.get("server_instance_id",""));equal(1,pushes[0]);
            editor.put("amount",30);f.save(editor);equal(false,a.sync());equal(1,pushes[0]);equal("instance_context_mismatch",f.query("SELECT error FROM outbox ORDER BY seq DESC").get(0).optString("error"));
        }finally{f.close();target.deleteDatabase(name);}log.append("Discovered instance context, unbound-queue quarantine and replacement-service/editor fence: PASS\n");
    }
