    private Object field(Activity a,String name)throws Exception{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(a);}
    private void injectVoice(Activity a,VoiceInput.BackendFactory factory)throws Exception{java.lang.reflect.Field f=MainActivity.class.getDeclaredField("voice");f.setAccessible(true);java.lang.reflect.Method nav=MainActivity.class.getDeclaredMethod("nav",String.class);nav.setAccessible(true);Object old=field(a,"composer");runOnMainSync(()->{try{f.set(a,new VoiceInput(a,factory));nav.invoke(a,"today");}catch(Exception e){throw new RuntimeException(e);}});long limit=android.os.SystemClock.elapsedRealtime()+7000;boolean[] fresh={false};while(!fresh[0]&&android.os.SystemClock.elapsedRealtime()<limit){runOnMainSync(()->{try{fresh[0]=field(a,"composer")!=old&&hasText(a.getWindow().getDecorView(),"说话");}catch(Exception e){throw new RuntimeException(e);}});if(!fresh[0])Thread.sleep(50);}if(!fresh[0])throw new AssertionError("Injected voice composer did not render");waitForIdleSync();}
    private boolean hasText(android.view.View view,String text){if(!view.isShown())return false;if(view instanceof android.widget.TextView&&text.contentEquals(((android.widget.TextView)view).getText()))return true;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++)if(hasText(g.getChildAt(i),text))return true;}return false;}
    private void waitText(Activity a,String text)throws Exception{long limit=android.os.SystemClock.elapsedRealtime()+7000;boolean[] found={false};do{runOnMainSync(()->found[0]=hasText(a.getWindow().getDecorView(),text));if(found[0])return;Thread.sleep(50);}while(android.os.SystemClock.elapsedRealtime()<limit);throw new AssertionError("Missing UI state "+text);}
    private void waitFrames()throws Exception{long limit=android.os.SystemClock.elapsedRealtime()+4000;while(android.os.SystemClock.elapsedRealtime()<limit){File[] fs=target.getCacheDir().listFiles();if(fs!=null)for(File f:fs)if(f.getName().startsWith("capture-")&&f.length()>1644)return;Thread.sleep(50);}throw new AssertionError("Native microphone did not write frames");}
    private void waitForm(Activity a)throws Exception{long limit=android.os.SystemClock.elapsedRealtime()+7000;while(field(a,"formAmount")==null&&android.os.SystemClock.elapsedRealtime()<limit)Thread.sleep(50);equal(true,field(a,"formAmount")!=null);String[] amount={""};runOnMainSync(()->{try{amount[0]=((android.widget.EditText)field(a,"formAmount")).getText().toString();}catch(Exception e){throw new RuntimeException(e);}});equal("123",amount[0]);Dialog dialog=(Dialog)field(a,"sheet");equal(true,dialog.isShowing());runOnMainSync(()->((AlertDialog)dialog).getButton(-2).performClick());}
