    private void longRecording()throws Exception{Activity a=startActivitySync(new android.content.Intent(target,MainActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();waitText(a,"说话");runOnMainSync(()->clickText(a.getWindow().getDecorView(),"说话"));waitFrames();Object composer=field(a,"composer");Thread.sleep(65000);VoiceInput v=(VoiceInput)field(a,"voice");if(!v.active())throw new AssertionError("65-second microphone is no longer active");equal(true,v.active());waitText(a,"结束录音");if(composer!=field(a,"composer"))throw new AssertionError("65-second composer was replaced");equal(true,composer==field(a,"composer"));long bytes=0;File[] fs=target.getCacheDir().listFiles();if(fs!=null)for(File f:fs)if(f.getName().startsWith("capture-"))bytes=Math.max(bytes,f.length());if(bytes<=SpeechAudio.BYTES_PER_SECOND*60L)throw new AssertionError("65-second PCM payload too short: "+bytes);equal(true,bytes>SpeechAudio.BYTES_PER_SECOND*60L);runOnMainSync(()->clickText(a.getWindow().getDecorView(),"取消语音"));Thread.sleep(500);equal(false,v.active());equal(false,SpeechDrafts.exists(target));runOnMainSync(a::finish);log.append("Actual 65-second AudioRecord continues through minute refresh; cancel releases without ASR upload: PASS\n");}
