    private static boolean clickText(android.view.View view,String text){if(view instanceof android.widget.TextView&&text.contentEquals(((android.widget.TextView)view).getText())&&view.isClickable()){view.performClick();return true;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int k=0;k<group.getChildCount();k++)if(clickText(group.getChildAt(k),text))return true;}return false;}
